SELECT DISTINCT y.COMPANY_ID VENDOR_ID, y.CATEGORY_NAME, y.PJ_ORG_STATUS, y.PJ_CATEGORY_STATUS, y.SERVICE_STATUS
FROM cloud_biz_supplier.scc_sup_org_category y
INNER JOIN meicloud_bpmp_material.mt_classification mt ON y.CATEGORY_ID = mt.id AND mt.level = 4

    AND y.COMPANY_ID IN

        #{vendorId}


        AND y.CATEGORY_ID =#{categoryId}
